{%- if share >= 85 -%}{%- assign band = "b-max" -%}
{%- elsif share >= 60 -%}{%- assign band = "b-heavy" -%}
{%- elsif share >= 25 -%}{%- assign band = "b-normal" -%}{%- endif -%}
<div class="verdict {{ band }}">
